fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let len = s.len();
    let p = len - (len % 3);

    let mut res = Vec::with_capacity(len);

    for i in 0..p {
        match i % 3 {
            0 => res.push(s[i + 2]),
            1 => res.push(s[i - 1]),
            2 => res.push(s[i]), // Unchanged for indices where i mod 3 == 2
            _ => unreachable!(),
        }
    }

    for i in p..len {
        res.push(s[i]);
    }

    res
}